from lib import *
S = SS('k3')
W = [['请求体', 'YAML / JSON'], ['剪枝', '删掉 schema 外字段'], ['补默认值', 'default:'], ['schema 校验', '类型 / 范围 / 必填'], ['写入 etcd', '默认值已固化'], ['读出时', '再补新默认值']]
E2 = [['/widgets/w1', '主资源'], ['/widgets/w1/status', 'status 子资源']]
PANELS = [('f', 'flow', 'CRD 对象的写入与读出'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("CRD 里声明 spec.size 必填且 1..10、spec.color 枚举 red/green 默认 red。size=3 的对象被接受,读回来 spec 是 {\"color\":\"red\",\"size\":3}——color 是服务端补的。size=0 → Invalid value: 0 … should be greater than or equal to 1;缺 size → Required value;color=blue → Unsupported value: \"blue\": supported values: \"red\", \"green\";size=\"abc\" → must be of type integer。kubectl get 的 SIZE、COLOR 两列来自 additionalPrinterColumns。", f=fl(W, cur=[3], done=[0, 1, 2, 4]), t=tl(S(1), mark=lidx(S(1), '退出码 1'), done=lidx(S(1), '[size=3]', '读回 w1', 'w1     3')), kv=KV([['required / minimum / enum', '提交时就被拒绝,报错带字段路径'], ['default', '创建时补上 color: red'], ['additionalPrinterColumns', '决定 kubectl get 的列']], ['required / minimum / enum'])),
    step("schema 里没有的字段:kubectl 默认的服务端严格字段校验直接拒绝,报 strict decoding error: unknown field \"spec.extra\";--validate=false 时请求被接受,但读回来 spec 只有 {\"color\":\"red\",\"size\":2},extra 被剪掉了;--validate=warn 接受并给出 Warning: unknown field \"spec.extra\"。", f=fl(W, cur=[1], done=[0, 2, 3, 4]), t=tl(S(2), mark=lidx(S(2), 'strict decoding error', 'extra 不见了'), done=lidx(S(2), '--validate=warn')), kv=KV([['默认', '严格校验:未知字段报错'], ['--validate=false', '静默剪掉(pruning)'], ['--validate=warn', '剪掉并给出 Warning']], ['--validate=false'])),
    step("etcd 里 w1 存的是 {\"color\": \"red\", \"size\": 3}——写入时补的默认值已经固化。之后给 CRD 新增带默认值的字段 spec.shape(default: circle):读 w1 得到 {\"color\":\"red\",\"shape\":\"circle\",\"size\":3},但 etcd 里的 spec 仍然没有 shape——新默认值是在读出来的时候补上的。", f=fl(W, cur=[4, 5], done=[0, 1, 2, 3]), t=tl(S(3), mark=lidx(S(3), '存进去的 JSON', 'etcd 里 w1 的 spec'), done=lidx(S(3), '读 w1 的 spec')), kv=KV([['写入时', '默认值固化进 etcd'], ['CRD 新增默认值', '读出来时补,etcd 不变'], ['含义', '新默认值不会改写旧对象']], ['CRD 新增默认值'])),
    step("开了 status 子资源:patch 主资源写 status.ready=true,读回 status 仍是空;改走 --subresource=status 写同样的内容才生效(generation 仍是 1);通过 status 子资源改 spec.size=9 显示 (no change),size 仍是 3;通过主资源改 spec.size=5 生效,generation 变成 2。", f=fl(E2, cur=[1], mark=[0]), t=tl(S(4), mark=lidx(S(4), '读回 status=(空)', '(no change)'), done=lidx(S(4), 'generation=2', '读回 status={"ready":true}')), kv=KV([['主资源', '写 spec 生效,写 status 被忽略'], ['/status', '写 status 生效,写 spec 被忽略'], ['generation', '只在 spec 变化时加 1']], ['generation'])),
]
A = mkartk('k3', 3, 'Kubernetes,CRD,CustomResourceDefinition,schema 校验,pruning,status 子资源,真实验证,动画演示',
    '在 kind 集群里创建一个带 openAPIV3Schema 的 CRD 并逐项实测:必填、范围、枚举、类型校验各自的报错;未知字段在 kubectl 严格校验下被拒绝、用 --validate=false 提交时被剪掉;etcd 里存的 JSON 只含写入时补的默认值,CRD 事后新增的默认值是读出来时才补;开了 status 子资源之后主资源和 /status 各自忽略对方的字段,generation 只跟着 spec 变化。',
    '写一个 CRD 之后,你的自定义资源在 API Server 里到底得到了哪些待遇?这篇把 schema 校验、剪枝、默认值和 status 子资源一项项真的跑了一遍,并直接去 etcd 里把存下来的 JSON 读出来,看默认值是什么时候被补上的。',
    [('4 种报错', 'size=0、缺 size、color=blue、size 写成字符串各自被 schema 拒绝时的报错'), ('{"color":"red","size":3}', 'etcd 里存的 spec:CRD 事后新增的 shape 默认值不在其中'), ('generation 1 → 2', '只有通过主资源改 spec 才会增加,写 status 不会')],
    [('schema 校验', '<p>CRD 的 <code>openAPIV3Schema</code> 在提交时就起作用:<code>size=0</code> 报 <code>should be greater than or equal to 1</code>,缺 <code>size</code> 报 <code>Required value</code>,<code>color=blue</code> 报 <code>Unsupported value</code> 并列出允许的值,类型错的报 <code>must be of type integer</code>。合法对象读回来多了 <code>color: red</code>,是 <code>default</code> 补的。<code>kubectl get</code> 的 SIZE、COLOR 两列来自 <code>additionalPrinterColumns</code>。</p>'),
     ('未知字段', '<p>schema 里没声明的字段不会被保留。kubectl 默认开着服务端严格字段校验,直接报 <code>strict decoding error: unknown field "spec.extra"</code>;用 <code>--validate=false</code> 绕过去,请求被接受,但读回来 <code>extra</code> 已经被剪掉(pruning);<code>--validate=warn</code> 则是剪掉并给出 Warning。想保留未知字段要在 schema 里写 <code>x-kubernetes-preserve-unknown-fields: true</code>。</p>'),
     ('etcd 里存了什么', '<p>CR 以 JSON 存在 <code>/registry/&lt;group&gt;/&lt;resource&gt;/&lt;ns&gt;/&lt;name&gt;</code>。w1 存进去的 spec 是 <code>{"color": "red", "size": 3}</code>:写入时补的默认值已经固化。之后给 CRD 加一个带默认值的字段 <code>shape</code>,读 w1 马上看到 <code>"shape":"circle"</code>,但 etcd 里的 spec 一个字没变——CRD 事后新增的默认值是在读出来的时候补上的,不会改写旧对象。</p>'),
     ('status 子资源', '<p>开了 <code>subresources.status</code> 之后,主资源和 <code>/status</code> 各管各的:往主资源 patch <code>status</code> 被忽略,往 <code>/status</code> patch <code>spec</code> 也被忽略(<code>no change</code>)。<code>metadata.generation</code> 只在 spec 变化时加 1,所以控制器可以用 <code>generation</code> 和 <code>status.observedGeneration</code> 判断自己处理的是不是最新的 spec。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);CRD widgets.k3.example.com(v1,spec.size 必填且 1..10,spec.color 枚举 red/green 默认 red,status 子资源,两个附加打印列);etcd 里的 JSON 用 etcd 静态 Pod 里的 etcdctl get --print-value-only 读出;实验后删除了 CRD 与命名空间;每种情形各一次',
     '没有验证:x-kubernetes-preserve-unknown-fields、x-kubernetes-embedded-resource;nullable 与默认值的交互;CEL 校验规则(后面有专门的文章);CRD 的结构化 schema 要求(非结构化 schema 被拒绝);scale 子资源;大对象(超过 etcd 请求大小限制)的行为'],
    'CRD 的写入与读出', PANELS)
